use std::io::*;

const N: usize = usize::MAX;

struct T {
    k: Vec<i64>,
    l: Vec<usize>,
    r: Vec<usize>,
    root: usize,
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut o = String::new();
    let mut t = T { k: vec![], l: vec![], r: vec![], root: N };
    for line in s.lines() {
        let mut p = line.split_whitespace();
        let c = match p.next() {
            Some(c) => c,
            None => continue,
        };
        let x: i64 = p.next().and_then(|v| v.parse().ok()).unwrap_or(0);
        match c {
            "insert" | "contains" | "delete" => {
                let mut par = N;
                let mut cur = t.root;
                while cur != N && t.k[cur] != x {
                    par = cur;
                    cur = if x < t.k[cur] { t.l[cur] } else { t.r[cur] };
                }
                if c == "insert" {
                    if cur != N {
                        o.push_str("dup\n");
                    } else {
                        t.k.push(x);
                        t.l.push(N);
                        t.r.push(N);
                        let id = t.k.len() - 1;
                        if par == N {
                            t.root = id;
                        } else if x < t.k[par] {
                            t.l[par] = id;
                        } else {
                            t.r[par] = id;
                        }
                        o.push_str("ok\n");
                    }
                } else if c == "contains" {
                    o.push_str(if cur != N { "yes\n" } else { "no\n" });
                } else if cur == N {
                    o.push_str("missing\n");
                } else {
                    if t.l[cur] != N && t.r[cur] != N {
                        let mut sp = cur;
                        let mut sc = t.r[cur];
                        while t.l[sc] != N {
                            sp = sc;
                            sc = t.l[sc];
                        }
                        t.k[cur] = t.k[sc];
                        if sp == cur {
                            t.r[sp] = t.r[sc];
                        } else {
                            t.l[sp] = t.r[sc];
                        }
                    } else {
                        let ch = if t.l[cur] != N { t.l[cur] } else { t.r[cur] };
                        if par == N {
                            t.root = ch;
                        } else if t.l[par] == cur {
                            t.l[par] = ch;
                        } else {
                            t.r[par] = ch;
                        }
                    }
                    o.push_str("ok\n");
                }
            }
            "inorder" => {
                let mut v = vec![];
                let mut st = vec![];
                let mut cur = t.root;
                while cur != N || !st.is_empty() {
                    while cur != N {
                        st.push(cur);
                        cur = t.l[cur];
                    }
                    let n: usize = st.pop().unwrap();
                    v.push(t.k[n].to_string());
                    cur = t.r[n];
                }
                if v.is_empty() {
                    o.push_str("<empty>\n");
                } else {
                    o.push_str(&v.join(" "));
                    o.push('\n');
                }
            }
            "height" => {
                let mut h = 0;
                let mut st = vec![];
                if t.root != N {
                    st.push((t.root, 1));
                }
                while let Some((n, d)) = st.pop() {
                    if d > h {
                        h = d;
                    }
                    if t.l[n] != N {
                        st.push((t.l[n], d + 1));
                    }
                    if t.r[n] != N {
                        st.push((t.r[n], d + 1));
                    }
                }
                o.push_str(&format!("{}\n", h));
            }
            "min" | "max" => {
                if t.root == N {
                    o.push_str("empty\n");
                } else {
                    let mut n = t.root;
                    loop {
                        let nx = if c == "min" { t.l[n] } else { t.r[n] };
                        if nx == N {
                            break;
                        }
                        n = nx;
                    }
                    o.push_str(&format!("{}\n", t.k[n]));
                }
            }
            _ => {}
        }
    }
    print!("{}", o);
}

